<# Host-only controller. Schedules one pinned native executable directly;
   never stages a guest script or changes guest security or VM state. #>
[CmdletBinding()]
param([Parameter(Mandatory)][string]$ConversionDirectory,
 [Parameter(Mandatory)][ValidateSet('Verify','Mutate','VerifyAfterMutation')][string]$Operation,
 [Parameter(Mandatory)][string]$VerifierPath,
