 [string]$VerificationDirectory,[string]$MutationDirectory,[switch]$SourceOnlyAfterReboot)
Set-StrictMode -Version Latest;$ErrorActionPreference='Stop'
function Test-ExpectedHandoff([byte[]]$Bytes,[string]$Immutable,[string]$Target){
 if($Bytes.Length-ne4096-or$Immutable-cnotmatch'\A[0-9a-f]{64}\z'-or$Target-cnotmatch'\A[0-9a-f]{64}\z'){return $false}
 $expected=[byte[]]::new(4096);[Text.Encoding]::ASCII.GetBytes('N2RHND01').CopyTo($expected,0);$expected[8]=3
 for($i=0;$i-lt32;$i++){$expected[16+$i]=[Convert]::ToByte($Immutable.Substring(2*$i,2),16);$expected[48+$i]=[Convert]::ToByte($Target.Substring(2*$i,2),16)}
 $sha=[Security.Cryptography.SHA256]::Create();try{$sha.ComputeHash($expected,0,4064).CopyTo($expected,4064)}finally{$sha.Dispose()}
 [Convert]::ToBase64String($Bytes)-ceq[Convert]::ToBase64String($expected)
}
function Read-PostcheckPin([string]$Path,[string]$Sha,[long]$Limit){
 $f=Get-Item -LiteralPath $Path -Force
 if($Sha-cnotmatch'\A[0-9a-f]{64}\z'-or$f.PSIsContainer-or($f.Attributes-band[IO.FileAttributes]::ReparsePoint)-or$f.Length-gt$Limit-or(Get-FileHash -LiteralPath $Path).Hash.ToLowerInvariant()-cne$Sha){throw ('Pinned ordinary file differs: '+$Path)}
 Get-Content -LiteralPath $Path -Raw|ConvertFrom-Json
}
function Assert-StrictPostcheckTree($Report,$Config,[string]$MutationSha){
 if($Report.kind-cne'general-post-handoff-refs-verification'-or-not$Report.success-or-not$Report.ordinary_tree_verified-or$Report.diagnostic_only-or-not$Report.observation_complete-or$Report.filesystem-cne'ReFS'-or$Report.mount_paths_preserved-ne$true-or$Report.request_sha256-cne$Config.requestSha256-or$Report.expected_tree_sha256-cne$Config.expectationSha256-or@($Report.native.native.objects).Count-ne$Config.expectedObjectCount-or[bool]$Report.post_mutation_root_policy-ne[bool]$MutationSha-or($MutationSha-and$Report.mutation_report_sha256-cne$MutationSha)){throw 'Complete strict native verification differs.'}
}
function Assert-PostcheckMutation($Report,[string]$RunId,[string]$RootBefore){
 if($Report.kind-cne'general-refs-mutation-workload'-or$Report.run_id-cne$RunId-or$Report.initial_bytes-ne50MB-or$Report.grown_bytes-ne80MB-or$Report.truncated_bytes-ne10MB-or$Report.directory_entries_created-ne128-or-not$Report.mutation_directory_removed-or-not$Report.only_new_test_paths_written-or$Report.root_basic_before.Count-ne40-or$Report.root_basic_after.Count-ne40){throw 'Complete bounded mutation evidence required.'}
 $before=[byte[]]$Report.root_basic_before;$after=[byte[]]$Report.root_basic_after
 if([Convert]::ToBase64String($before)-cne$RootBefore-or[Convert]::ToBase64String($before[0..7])-cne[Convert]::ToBase64String($after[0..7])-or[Convert]::ToBase64String($before[32..39])-cne[Convert]::ToBase64String($after[32..39])){throw 'Mutation root policy differs from pinned premutation evidence.'}
}
function Get-NativePostcheckObservation($Session,$Config){
 Invoke-Command -Session $Session -ArgumentList $Config -ScriptBlock {
  param($Config);Set-StrictMode -Version Latest;$ErrorActionPreference='Stop'
  $original=Get-ScheduledTask -TaskName $Config.originalTaskName;$oi=Get-ScheduledTaskInfo -TaskName $Config.originalTaskName
  $active=@(Get-ScheduledTask -TaskName 'N2R-*' -ErrorAction SilentlyContinue|Where-Object {$_.TaskName-cne$Config.taskName-and$_.State-in@('Running','Queued')}|Select-Object -ExpandProperty TaskName)
  $workers=@(Get-CimInstance Win32_Process|Where-Object {$_.ExecutablePath-and$_.ExecutablePath.StartsWith('C:\ntfs2refs\',[StringComparison]::OrdinalIgnoreCase)}|Select-Object -ExpandProperty ProcessId)
  $disks=@(foreach($number in @(1,2)){$d=Get-Disk -Number $number;$p=Get-Partition -DiskNumber $number -PartitionNumber 2;[pscustomobject]@{number=$number;guid=[string]$d.Guid;partitionGuid=[string]$p.Guid;bytes=[long]$d.Size;partitionBytes=[long]$p.Size;offset=[long]$p.Offset;logical=[int]$d.LogicalSectorSize;physical=[int]$d.PhysicalSectorSize;offline=[bool]$d.IsOffline;readOnly=[bool]$d.IsReadOnly;boot=[bool]$d.IsBoot;system=[bool]$d.IsSystem;partitionBoot=[bool]$p.IsBoot;partitionSystem=[bool]$p.IsSystem;style=[string]$d.PartitionStyle}})
  $sourcePart=Get-Partition -DiskNumber 1 -PartitionNumber 2;$volume=$sourcePart|Get-Volume;$jv=Get-Partition -DiskNumber 2 -PartitionNumber 2|Get-Volume;$letter=Get-Partition -DriveLetter F
  $shadows=@(Get-Disk|Where-Object {$_.Number-eq3-or([string]$_.Guid-and[guid]$_.Guid-eq[guid]'49dbc2d2-4120-4fbf-911d-0f8d58153598')})
  $shadow=$null
  if($shadows.Count-eq1){$d=$shadows[0];$p=Get-Partition -DiskNumber $d.Number -PartitionNumber 2;$shadow=[pscustomobject]@{number=$d.Number;guid=[string]$d.Guid;partitionGuid=[string]$p.Guid;bytes=[long]$d.Size;partitionBytes=[long]$p.Size;offset=[long]$p.Offset;logical=[int]$d.LogicalSectorSize;physical=[int]$d.PhysicalSectorSize;offline=[bool]$d.IsOffline;readOnly=[bool]$d.IsReadOnly;boot=[bool]$d.IsBoot;system=[bool]$d.IsSystem;partitionBoot=[bool]$p.IsBoot;partitionSystem=[bool]$p.IsSystem}}
  $pins=@(foreach($pin in $Config.pins){$path=Join-Path $Config.inputRoot $pin.name;$f=Get-Item -LiteralPath $path -Force;if($f.PSIsContainer-or($f.Attributes-band[IO.FileAttributes]::ReparsePoint)-or$f.Length-gt$pin.limit){throw 'Copied native input is not bounded ordinary data.'};[pscustomobject]@{name=$pin.name;sha256=(Get-FileHash -LiteralPath $path).Hash.ToLowerInvariant()}})
  $journal=Get-Item -LiteralPath $Config.journal -Force;if($journal.PSIsContainer-or($journal.Attributes-band[IO.FileAttributes]::ReparsePoint)){throw 'Closed journal is not an ordinary file.'}
  $stream=[IO.File]::Open($Config.journal,[IO.FileMode]::Open,[IO.FileAccess]::Read,[IO.FileShare]::ReadWrite)
  try{$marker=[byte[]]::new(4096);$at=0;while($at-lt4096){$n=$stream.Read($marker,$at,4096-$at);if($n-eq0){throw 'Closed journal marker truncated.'};$at+=$n}}finally{$stream.Dispose()}
  $prior=$null
  if($Config.prerequisiteTaskName){$t=Get-ScheduledTask -TaskName $Config.prerequisiteTaskName;$i=Get-ScheduledTaskInfo -TaskName $Config.prerequisiteTaskName;$prior=[pscustomobject]@{state=[string]$t.State;exitCode=$i.LastTaskResult;runYear=$i.LastRunTime.Year;runUtcTicks=$i.LastRunTime.ToUniversalTime().Ticks;sha256=(Get-FileHash -LiteralPath $Config.prerequisiteGuestOutput).Hash.ToLowerInvariant()}}
  [pscustomobject]@{computer=$env:COMPUTERNAME;systemDrive=$env:SystemDrive;originalState=[string]$original.State;originalExit=$oi.LastTaskResult;originalRunYear=$oi.LastRunTime.Year;activeTasks=$active;activeWorkers=$workers;disks=$disks;driveLetter=[string]$sourcePart.DriveLetter;letterDisk=$letter.DiskNumber;letterPartition=$letter.PartitionNumber;filesystem=[string]$volume.FileSystem;clusterBytes=$volume.AllocationUnitSize;labelUtf16=@(([string]$volume.FileSystemLabel).ToCharArray()|ForEach-Object {[int]$_});journalFilesystem=[string]$jv.FileSystem;shadowCount=$shadows.Count;shadow=$shadow;pins=$pins;journalBytes=$journal.Length;markerBase64=[Convert]::ToBase64String($marker);bootUtcTicks=([DateTime](Get-CimInstance Win32_OperatingSystem).LastBootUpTime).ToUniversalTime().Ticks;prerequisite=$prior;readOnlyObservation=$true}
 }
}
function Assert-NativePostcheckObservation($State,$Config){
 if($State.computer-cne'N2R-WIN11'-or$State.systemDrive-cne'C:'-or$State.originalState-in@('Running','Queued')-or$State.originalExit-ne0-or$State.originalRunYear-lt2000-or$State.activeTasks.Count-or$State.activeWorkers.Count){throw 'Owned guest and known completed conversion with no live work required.'}
 foreach($spec in @(@(1,'a01574d5-2a5c-4136-958a-dcf0d0e0f7aa','79eaccdf-38d3-4561-97cc-9276af5d223a',64GB,52GB),@(2,'04d5194b-f5db-43da-9b02-ed7a54325d56','7435ee94-c435-403f-a515-dec1ccd5094e',8GB,(8GB-32MB)))){
  $ds=@($State.disks|Where-Object {$_.number-eq$spec[0]});if($ds.Count-ne1){throw 'Expected disk missing.'};$d=$ds[0]
  if([guid]$d.guid-ne[guid]$spec[1]-or[guid]$d.partitionGuid-ne[guid]$spec[2]-or$d.bytes-ne$spec[3]-or$d.partitionBytes-ne$spec[4]-or$d.offset-ne16MB-or$d.logical-ne512-or$d.physical-ne4096-or$d.offline-or$d.readOnly-or$d.boot-or$d.system-or$d.partitionBoot-or$d.partitionSystem-or$d.style-cne'GPT'){throw 'Source/journal native identity, geometry or online state differs.'}
 }
 if($State.driveLetter-cne'F'-or$State.letterDisk-ne1-or$State.letterPartition-ne2-or$State.filesystem-cne'ReFS'-or$State.clusterBytes-ne4096-or$State.journalFilesystem-cne'NTFS'-or[string]::Join(',',@($State.labelUtf16))-cne[string]::Join(',',@($Config.sourceLabelUtf16))){throw 'Original ReFS mount, geometry or exact source label differs.'}
 if($Config.sourceOnlyAfterReboot){if($State.shadowCount-ne0-or$State.bootUtcTicks-le$Config.priorBootUtcTicks){throw 'Explicit source-only observation requires absent shadow and a newer boot.'}}
 else{$d=$State.shadow;if($State.shadowCount-ne1-or-not$d-or$d.number-ne3-or[guid]$d.guid-ne[guid]'49dbc2d2-4120-4fbf-911d-0f8d58153598'-or[guid]$d.partitionGuid-ne[guid]'e071a0c1-5f96-4327-85e8-da9b831e27d3'-or$d.bytes-ne64GB-or$d.partitionBytes-ne52GB-or$d.offset-ne16MB-or$d.logical-ne512-or$d.physical-ne4096-or-not$d.offline-or-not$d.readOnly-or$d.boot-or$d.system-or$d.partitionBoot-or$d.partitionSystem){throw 'Enrolled shadow must remain offline/read-only.'};if($Config.priorBootUtcTicks-gt0-and$State.bootUtcTicks-ne$Config.priorBootUtcTicks){throw 'Non-postboot verification changed boot context.'}}
 if($State.journalBytes-ne$Config.journalLength-or-not(Test-ExpectedHandoff ([Convert]::FromBase64String($State.markerBase64)) $Config.immutableSha256 $Config.expectedPostimageSha256)){throw 'Exact complete ticket/postimage-bound HND sector required.'}
 foreach($pin in $Config.pins){$actual=@($State.pins|Where-Object {$_.name-ceq$pin.name});if($actual.Count-ne1-or$actual[0].sha256-cne$pin.sha256){throw 'Native copied input/executable pin differs.'}}
 if($Config.prerequisiteTaskName){$p=$State.prerequisite;if(-not$p-or$p.state-in@('Running','Queued')-or$p.exitCode-ne0-or$p.runYear-lt2000-or$p.sha256-cne$Config.prerequisiteReportSha256-or($Config.operation-ceq'Mutate'-and$p.runUtcTicks-lt$State.bootUtcTicks)){throw 'Current-branch completed prerequisite differs.'}}
}
