$output=Assert-LabPath (Join-Path $cfg.Root ('native-public-postcheck/win11-'+[DateTime]::UtcNow.ToString('yyyyMMddTHHmmssfffZ'))) $cfg.Root;New-Item -ItemType Directory -Path $output|Out-Null
function Save([string]$Name,$Value){$b=[Text.UTF8Encoding]::new($false).GetBytes(($Value|ConvertTo-Json -Depth 18));$f=[IO.File]::Open((Join-Path $output $Name),[IO.FileMode]::CreateNew,[IO.FileAccess]::Write,[IO.FileShare]::Read);try{$f.Write($b,0,$b.Length);$f.Flush($true)}finally{$f.Dispose()}}
Save 'configuration.json' $config;$configSha=(Get-FileHash (Join-Path $output 'configuration.json')).Hash.ToLowerInvariant()
$dispatch=[ordered]@{schemaVersion=2;kind='native-public-postcheck-dispatch';stepId=$step;originRunId=$original.runId;conversionDirectory=$origin;operation=$Operation;sourceOnlyAfterReboot=[bool]$SourceOnlyAfterReboot;verificationDirectory=$VerificationDirectory;mutationDirectory=$MutationDirectory;vmId=[string]$vm.Id;checkpointId=[string]$vm.ParentSnapshotId;taskName=$taskName;guestRoot=$root;guestOutput=$nativeOutput;configurationSha256=$configSha;binarySha256=$binary.sha256;requestSha256=$config.requestSha256;expectationSha256=$config.expectationSha256;powershellWorkerLoaded=$false;securitySettingsChanged=$false;startedUtc=[DateTime]::UtcNow.ToString('o')};Save 'dispatch.json' $dispatch
$credential=Import-Clixml (Join-Path $cfg.Root 'win11/secrets/guest-credential.xml');$session=$null
try{
 $session=New-PSSession -VMId $vm.Id -Credential $credential -ErrorAction Stop
 Invoke-Command -Session $session -ArgumentList $root -ScriptBlock {param($Root)$ErrorActionPreference='Stop';if(Test-Path -LiteralPath $Root){throw 'Fresh native input/output directory required.'};$parent=Split-Path $Root -Parent;if(-not(Test-Path $parent)){New-Item -ItemType Directory -Path $parent|Out-Null};for($p=$parent;$p;$p=Split-Path $p -Parent){$i=Get-Item $p -Force;if(-not$i.PSIsContainer-or($i.Attributes-band[IO.FileAttributes]::ReparsePoint)){throw 'Ordinary native input ancestry required.'}};New-Item -ItemType Directory -Path $Root|Out-Null}|Out-Null
 foreach($artifact in $inputs){Copy-Item -LiteralPath $artifact.path -Destination (Join-Path $root $artifact.name) -ToSession $session}
 $state=Get-NativePostcheckObservation $session $config;Assert-NativePostcheckObservation $state $config;Save 'preflight.json' $state
 $arguments='--request "'+$root+'\request.json" --request-sha256 '+$config.requestSha256+' --output "'+$nativeOutput+'"'
 if($Operation-ceq'Mutate'){$arguments+=' --run-id '+$step}else{$arguments+=' --expectation "'+$root+'\expectation.json" --expectation-sha256 '+$config.expectationSha256;if($Operation-ceq'VerifyAfterMutation'){$arguments+=' --mutation-report "'+$root+'\mutation-proof.json" --mutation-report-sha256 '+$config.mutationReportSha256}}
 $started=Invoke-Command -Session $session -ArgumentList @((Join-Path $root $binary.name),$binary.sha256,$arguments,$nativeOutput,$taskName) -ScriptBlock {
  param($Exe,$ExeSha,$Arguments,$Output,$TaskName);$ErrorActionPreference='Stop'
  if((Get-FileHash -LiteralPath $Exe).Hash.ToLowerInvariant()-cne$ExeSha-or(Test-Path $Output)-or(Get-ScheduledTask -TaskName $TaskName -ErrorAction SilentlyContinue)-or@(Get-ScheduledTask -TaskName 'N2R-*' -ErrorAction SilentlyContinue|Where-Object {$_.State-in@('Running','Queued')}).Count){throw 'Native task inputs or lifecycle changed before dispatch.'}
  $action=New-ScheduledTaskAction -Execute $Exe -Argument $Arguments;$principal=New-ScheduledTaskPrincipal -UserId SYSTEM -LogonType ServiceAccount -RunLevel Highest;$settings=New-ScheduledTaskSettingsSet -ExecutionTimeLimit ([TimeSpan]::Zero)
  Register-ScheduledTask -TaskName $TaskName -Action $action -Principal $principal -Settings $settings|Out-Null;Start-ScheduledTask -TaskName $TaskName
  [pscustomobject]@{taskName=$TaskName;state=[string](Get-ScheduledTask -TaskName $TaskName).State;guestOutput=$Output;nativeExecutable=$Exe;powershellWorkerLoaded=$false;securitySettingsChanged=$false}
 };Save 'task.json' $started
 [pscustomobject]@{directory=$output;operation=$Operation;taskName=$taskName;guestOutput=$nativeOutput;expectedObjects=$config.expectedObjectCount;sourceOnlyAfterReboot=[bool]$SourceOnlyAfterReboot}
}finally{if($session){Remove-PSSession $session -ErrorAction SilentlyContinue}}
